trait Collision[A, B] { def collide(a: A, b: B): String }

object Collision extends LowPriorityCollision {
  implicit val circleSquare: Collision[Circle, Square] =
    (a, b) => s"circle ${a.radius} vs square ${b.side}"
}
trait LowPriorityCollision {
  implicit def flip[A, B](implicit c: Collision[B, A]): Collision[A, B] = (a, b) => c.collide(b, a)
}
def collide[A, B](a: A, b: B)(implicit c: Collision[A, B]): String = c.collide(a, b)
